#include "general_def.h"
#include "main.h"
#include "Button_Manager.h"
#include "OLED.h"
#include "OLED_Draws.h"
#include "alarm.h"
#include "ErrorManager.h"

void SystemClock_Config(void);

/**
 * @brief Application entry point.
 *
 * The initialization order matters: the alarm FSM reads the time from the RTC
 * and draws it on the display, so both must be initialized before
 * alarmFSM_init(). Any initialization error resets the microcontroller
 * through Error_Handler().
 *
 * @return This function never returns.
 */
int main(void)
{
    if ( HAL_Init() != HAL_OK ) {
    	Error_Handler();
    }
    SystemClock_Config();
    Buttons_Init();
    RTC_Init();
    OLED_Init();
    OLED_Clear();
    debounceFSM_init();
    alarmFSM_init();
    while (1)
    {
    	debounceFSM_update();
    	alarmFSM_update();
    }
}

